<?php

namespace App\Http\Middleware;

use Closure;
use Illuminate\Http\Request;
use Symfony\Component\HttpFoundation\Response;

class PublicAssetQrPresentation
{
    public function handle(Request $request, Closure $next): Response
    {
        $response = $next($request);
        $contentType = (string) $response->headers->get('Content-Type');
        if (! str_contains($contentType, 'text/html')) return $response;

        $html = $response->getContent();
        if (! is_string($html) || ! str_contains($html, 'id="requestForm"') || str_contains($html, 'id="assetQrSection"')) return $response;

        $rtl = $request->query('lang') !== 'en';
        $copy = $rtl ? [
            'title'=>'تحديد المعدة من سجل أصول UNIFCO','optional'=>'اختياري','desc'=>'إذا كانت المعدة مسجلة لدى UNIFCO، امسح رمز QR الموجود عليها لتعبئة بياناتها الأساسية تلقائيًا.','scan'=>'مسح QR للمعدة','scanHint'=>'اضغط لفتح الكاميرا والمسح','manual'=>'أو أدخل رقم الأصل يدويًا','manualPlaceholder'=>'مثال: AST-2024-000123','find'=>'بحث','found'=>'تم التعرف على المعدة بنجاح','registry'=>'تم جلب البيانات من سجل أصول UNIFCO','asset'=>'رقم الأصل','name'=>'اسم الأصل','brand'=>'العلامة التجارية','model'=>'الموديل','serial'=>'الرقم التسلسلي','location'=>'الموقع','status'=>'الحالة','close'=>'إغلاق','camera'=>'وجّه الكاميرا نحو رمز QR الموجود على المعدة','notFound'=>'لم يتم العثور على المعدة. تحقق من رمز QR أو رقم الأصل.','cameraError'=>'تعذر تشغيل الكاميرا. يمكنك إدخال رقم الأصل يدويًا.','loading'=>'جاري البحث...'
        ] : [
            'title'=>'Identify Equipment from UNIFCO Asset Registry','optional'=>'Optional','desc'=>'If the equipment is registered with UNIFCO, scan its QR code to automatically fill its core details.','scan'=>'Scan Equipment QR','scanHint'=>'Tap to open the camera and scan','manual'=>'or enter the Asset ID manually','manualPlaceholder'=>'Example: AST-2024-000123','find'=>'Find','found'=>'Equipment identified successfully','registry'=>'Data loaded from the UNIFCO Asset Registry','asset'=>'Asset ID','name'=>'Asset Name','brand'=>'Brand','model'=>'Model','serial'=>'Serial Number','location'=>'Location','status'=>'Status','close'=>'Close','camera'=>'Point the camera at the QR code on the equipment','notFound'=>'Equipment was not found. Check the QR code or Asset ID.','cameraError'=>'Camera could not be started. You can enter the Asset ID manually.','loading'=>'Searching...'
        ];

        $section = '<section class="section asset-qr-section" id="assetQrSection"><div class="asset-qr-heading"><div><h2>'.$copy['title'].' <span class="asset-optional">'.$copy['optional'].'</span></h2><p>'.$copy['desc'].'</p></div><span class="asset-shield">UNIFCO ASSET 360</span></div><div class="asset-qr-layout"><button class="asset-scan-card" type="button" id="assetScanButton"><span class="asset-qr-icon">⌗</span><b>'.$copy['scan'].'</b><small>'.$copy['scanHint'].'</small></button><div class="asset-manual"><span>'.$copy['manual'].'</span><div class="asset-manual-row"><input type="text" id="assetManualKey" placeholder="'.$copy['manualPlaceholder'].'" autocomplete="off"><button type="button" id="assetManualFind">'.$copy['find'].'</button></div><div class="asset-lookup-message" id="assetLookupMessage" aria-live="polite"></div></div></div><div class="asset-result" id="assetResult" hidden><div class="asset-result-head"><span class="asset-check">✓</span><div><b>'.$copy['found'].'</b><small>'.$copy['registry'].'</small></div></div><div class="asset-result-grid"><div><span>'.$copy['asset'].'</span><strong data-asset="asset_code">—</strong></div><div><span>'.$copy['name'].'</span><strong data-asset="name">—</strong></div><div><span>'.$copy['brand'].'</span><strong data-asset="brand">—</strong></div><div><span>'.$copy['model'].'</span><strong data-asset="model">—</strong></div><div><span>'.$copy['serial'].'</span><strong data-asset="serial_number">—</strong></div><div><span>'.$copy['location'].'</span><strong data-asset="location">—</strong></div><div><span>'.$copy['status'].'</span><strong data-asset="status">—</strong></div></div></div></section><div class="asset-qr-modal" id="assetQrModal" hidden><div class="asset-qr-dialog"><div class="asset-qr-dialog-head"><div><b>'.$copy['scan'].'</b><small>'.$copy['camera'].'</small></div><button type="button" id="assetQrClose" aria-label="'.$copy['close'].'">×</button></div><div id="assetQrReader"></div><div class="asset-lookup-message" id="assetCameraMessage"></div></div></div>';

        $html = str_replace('<section class="section"><h2 id="technicalSectionTitle">', $section.'<section class="section"><h2 id="technicalSectionTitle">', $html);

        $css = '<style id="asset-qr-styles">.asset-qr-section{background:linear-gradient(135deg,#f8fbff,#fff);border:1px solid #d8e5f3!important;border-radius:16px;padding:20px!important}.asset-qr-heading{display:flex;justify-content:space-between;gap:14px;align-items:flex-start;margin-bottom:15px}.asset-optional{display:inline-block;font-size:8px;background:#eef6ff;color:#1d5c9f;padding:4px 8px;border-radius:999px;vertical-align:middle}.asset-shield{font-size:8px;font-weight:900;color:#2d6a45;background:#edf9f1;border:1px solid #c8ead3;padding:7px 9px;border-radius:8px;white-space:nowrap}.asset-qr-layout{display:grid;grid-template-columns:minmax(220px,.75fr) 1.25fr;gap:16px}.asset-scan-card{min-height:145px;border:1.5px dashed #7ca7d8;border-radius:14px;background:#f7fbff;color:#071f4d;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;cursor:pointer;font-family:inherit}.asset-scan-card:hover{border-color:#071f4d;background:#f0f6ff}.asset-qr-icon{font-size:42px;line-height:1;color:#0b5eb8}.asset-scan-card b{font-size:13px}.asset-scan-card small{font-size:8px;color:#76879a}.asset-manual{border:1px solid #e0e7ef;border-radius:14px;background:#fff;padding:18px;display:flex;flex-direction:column;justify-content:center;gap:10px}.asset-manual>span{font-size:10px;font-weight:800;color:#596b82}.asset-manual-row{display:grid;grid-template-columns:1fr auto;gap:8px}.asset-manual-row button{border:0;border-radius:9px;background:#071f4d;color:#fff;padding:0 18px;font:inherit;font-size:10px;font-weight:900;cursor:pointer}.asset-lookup-message{min-height:18px;font-size:9px;color:#9a2b3c}.asset-result{margin-top:14px;border:1px solid #bfe4c9;border-radius:14px;background:#f7fdf9;overflow:hidden}.asset-result-head{display:flex;align-items:center;gap:10px;padding:13px 15px;border-bottom:1px solid #d8efdf}.asset-check{width:27px;height:27px;border-radius:50%;display:grid;place-items:center;background:#22a657;color:#fff;font-weight:900}.asset-result-head b,.asset-result-head small{display:block}.asset-result-head b{font-size:11px;color:#16713c}.asset-result-head small{font-size:8px;color:#6a8b75}.asset-result-grid{display:grid;grid-template-columns:repeat(3,1fr)}.asset-result-grid>div{padding:11px 14px;border-inline-end:1px solid #e1eee5;border-bottom:1px solid #e1eee5}.asset-result-grid span,.asset-result-grid strong{display:block}.asset-result-grid span{font-size:8px;color:#73847a}.asset-result-grid strong{font-size:10px;color:#183a27;margin-top:3px}.asset-qr-modal{position:fixed;inset:0;background:rgba(4,20,43,.72);z-index:9999;padding:18px;display:grid;place-items:center}.asset-qr-modal[hidden]{display:none}.asset-qr-dialog{width:min(520px,100%);background:#fff;border-radius:18px;box-shadow:0 28px 80px rgba(0,0,0,.3);padding:18px}.asset-qr-dialog-head{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:14px}.asset-qr-dialog-head b,.asset-qr-dialog-head small{display:block}.asset-qr-dialog-head b{font-size:15px;color:#071f4d}.asset-qr-dialog-head small{font-size:9px;color:#7c899b;margin-top:3px}.asset-qr-dialog-head button{width:34px;height:34px;border:1px solid #dce4ed;background:#fff;border-radius:9px;font-size:22px;cursor:pointer}#assetQrReader{overflow:hidden;border-radius:12px}.asset-autofilled{background:#f5fbf7!important;border-color:#bfe4c9!important}@media(max-width:760px){.asset-qr-heading{display:block}.asset-shield{display:inline-block;margin-top:7px}.asset-qr-layout{grid-template-columns:1fr}.asset-result-grid{grid-template-columns:1fr 1fr}.asset-manual-row{grid-template-columns:1fr}.asset-manual-row button{min-height:44px}}</style>';
        $html = str_replace('</head>', $css.'</head>', $html);

        $jsCopy = json_encode($copy, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
        $js = '<script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script><script id="asset-qr-script">(()=>{const copy='.$jsCopy.',form=document.getElementById("requestForm"),result=document.getElementById("assetResult"),msg=document.getElementById("assetLookupMessage"),cameraMsg=document.getElementById("assetCameraMessage"),modal=document.getElementById("assetQrModal");if(!form)return;let hidden=form.querySelector("input[name=asset_id]");if(!hidden){hidden=document.createElement("input");hidden.type="hidden";hidden.name="asset_id";hidden.value="";form.appendChild(hidden)}const field=n=>form.querySelector(`[name="${n}"]`);const setVal=(n,v,locked=false)=>{if(v===null||v===undefined||v==="")return;const el=field(n);if(!el)return;if(el.tagName==="SELECT"){const norm=s=>String(s).toLowerCase().replace(/[_\-\s]+/g,"");let opt=[...el.options].find(o=>norm(o.value)===norm(v)||norm(o.textContent)===norm(v));if(!opt){opt=document.createElement("option");opt.value=v;opt.textContent=v;el.appendChild(opt)}el.value=opt.value;el.dispatchEvent(new Event("change",{bubbles:true}))}else el.value=v;if(locked)el.classList.add("asset-autofilled")};const setAreaCity=cityName=>{if(!cityName)return;try{const a=field("site_area"),c=field("site_city");if(typeof cities!=="undefined"){const areaKey=Object.keys(cities).find(k=>(cities[k]||[]).some(v=>String(v).toLowerCase()===String(cityName).toLowerCase()));if(areaKey){a.value=areaKey;a.dispatchEvent(new Event("change",{bubbles:true}))}}setTimeout(()=>setVal("site_city",cityName,true),0)}catch(e){setVal("site_city",cityName,true)}};const render=a=>{hidden.value=a.id;setVal("asset_type",a.type,true);setVal("equipment_brand",a.brand,true);setVal("equipment_model",a.model,true);setVal("company_name",a.customer_name,true);setVal("site_name",a.site_name,true);setVal("site_address",a.site_address,true);setVal("latitude",a.latitude);setVal("longitude",a.longitude);if(a.contact_name&&!field("responsible_person").value)setVal("responsible_person",a.contact_name,true);if(a.contact_mobile&&!field("mobile").value)setVal("mobile",a.contact_mobile,true);setAreaCity(a.site_city);const vals={asset_code:a.asset_code,name:a.name,brand:a.brand||"—",model:a.model||"—",serial_number:a.serial_number||"—",location:[a.site_name,a.site_city].filter(Boolean).join(" - ")||"—",status:a.operational_status||a.lifecycle_status||"—"};Object.entries(vals).forEach(([k,v])=>{const el=result.querySelector(`[data-asset="${k}"]`);if(el)el.textContent=v});result.hidden=false;msg.textContent="";result.scrollIntoView({behavior:"smooth",block:"nearest"})};const extractKey=raw=>{raw=String(raw||"").trim();try{const u=new URL(raw);return u.searchParams.get("asset")||u.searchParams.get("token")||u.pathname.split("/").filter(Boolean).pop()||raw}catch(e){return raw.replace(/^UNIFCO-ASSET:/i,"")}};const lookup=async raw=>{const key=extractKey(raw);if(!key)return;msg.textContent=copy.loading;try{const r=await fetch(`/service-assets/lookup?key=${encodeURIComponent(key)}`,{headers:{Accept:"application/json"}});if(!r.ok)throw new Error();const data=await r.json();render(data.asset);return true}catch(e){hidden.value="";result.hidden=true;msg.textContent=copy.notFound;return false}};document.getElementById("assetManualFind").addEventListener("click",()=>lookup(document.getElementById("assetManualKey").value));document.getElementById("assetManualKey").addEventListener("keydown",e=>{if(e.key==="Enter"){e.preventDefault();lookup(e.currentTarget.value)}});let scanner=null;const stop=async()=>{if(scanner){try{await scanner.stop()}catch(e){}try{scanner.clear()}catch(e){}scanner=null}modal.hidden=true};document.getElementById("assetQrClose").addEventListener("click",stop);modal.addEventListener("click",e=>{if(e.target===modal)stop()});document.getElementById("assetScanButton").addEventListener("click",async()=>{modal.hidden=false;cameraMsg.textContent="";if(typeof Html5Qrcode==="undefined"){cameraMsg.textContent=copy.cameraError;return}try{scanner=new Html5Qrcode("assetQrReader");await scanner.start({facingMode:"environment"},{fps:10,qrbox:{width:250,height:250}},async decoded=>{await stop();await lookup(decoded)},()=>{})}catch(e){cameraMsg.textContent=copy.cameraError}})})();</script>';
        $html = str_replace('</body>', $js.'</body>', $html);
        $response->setContent($html);
        return $response;
    }
}
